// A line regex cannot parse YAML, so the check fails closed, like the pin check (T-034): every
// line that mentions the action must be exactly a block step, indented with spaces only.
const MENTION = /actions\/checkout/;
const STEP = /^( *)(- +)?uses:[ \t]+actions\/checkout@[^ \t#]+(?:[ \t]+#.*)?[ \t]*$/;
const WITH = /^with:[ \t]*$/;
const OPTION = /^( +)persist-credentials:[ \t]+false[ \t]*$/;
const OPTION_KEY = /persist-credentials/;

/**
 * Finds the checkout steps in one workflow file that do not set `persist-credentials: false`.
 *
 * Input: the file's text and the name to report it under. Output: one problem per line that
 * mentions `actions/checkout`, unless that line is a block `uses:` step, the next line is
 * `with:` at the same column as `uses`, and the lines of that block (every following line
 * indented deeper than `with:`) hold `persist-credentials: false` exactly once, at the block's
 * own indentation, and mention the option nowhere else. Nothing is trimmed before a match
 * except the `\r` of a CRLF line ending. Never throws.
 */
export function persistedCredentials(text: string, file: string): CredentialProblem[] {
  const lines = text.split('\n').map(raw => (raw.endsWith('\r') ? raw.slice(0, -1) : raw));
  const problems: CredentialProblem[] = [];
  lines.forEach((line, index) => {
    if (!MENTION.test(line)) return;
    const report = (reason: string) => problems.push({ file, line: index + 1, reason });
    const step = STEP.exec(line);
    if (!step) {
      report('unsupported form: write the step as a block `uses: actions/checkout@<sha> # <release tag>`, and keep the action name out of other text');
      return;

// space before the colon, a comment, text in a `run:` string) is reported unless it is exactly
// a pinned STEP. Qodo local review findings 64a7ab3d, cb8ef482, ccd2f27a; PR 34 review finding
// 2dab9c1b. The false alarm on text is accepted (finding da3acbde).
const USES_WORD = /(?<![A-Za-z0-9_-])uses(?![A-Za-z0-9_-])/;
// An explicit key (`? key` with the value on a later line) is reported whatever the key says,
// so a key spelled across lines is never skipped (Qodo PR 34 review finding 3a2670fe).
const EXPLICIT_KEY = /^[ \t]*(?:-[ \t]+)?\?(?:[ \t]|$)/;
// A double-quoted key with a backslash escape: YAML reads `"\u0075ses"` as `uses`, which no
// text match sees (Qodo local review finding 5fa32f55). Any such key is reported. GitHub's
// repository setting `sha_pinning_required` is the control; this check is the early warning.

  problems.push({
    file,
    line: index + 1,
    action: line,
    reason: 'unsupported form: write the step as `uses: <owner>/<repo>@<sha> # <release tag>`, and keep `uses` out of other text',
  });
  return;
